fn solve(n: i8) -> Vec<char> {
    // We know 100 <= n <= 999, so casting to u8 is safe and gives the three‐digit value.
    let n_u = n as u8;
    // Extract each decimal digit.
    let hundreds = n_u / 100;
    let tens     = (n_u / 10) % 10;
    let ones     = n_u % 10;

    // Build the result vector: ['A', 'B', 'C', d1, d2, d3]
    vec![
        'A',
        'B',
        'C',
        (b'0' + hundreds) as char,
        (b'0' + tens)   as char,
        (b'0' + ones)   as char,
    ]
}

